export function computePartNo(
  categoryName: string,
  subcategoryName: string,
  threadTypeName: string,
  gradeName: string,
  size: string,
  finish: string,
  pitch?: string,
  length?: string,
  marking?: string,
  existingRows?: ProductRow[],
  currentRowId?: string
): string {
  let catAbbr = "HB";
  const catLower = (categoryName || "").toLowerCase();
  if (catLower.includes("anchor")) {
    catAbbr = "AB";
  } else if (catLower.includes("u bolt") || catLower.includes("u-bolt")) {
    catAbbr = "UB";
  } else if (catLower.includes("nut")) {
    catAbbr = "HN";
  } else if (catLower.includes("washer")) {
    catAbbr = "W";
  } else if (catLower.includes("round") || catLower.includes("bar")) {
    catAbbr = "RB";
  } else if (catLower.includes("pipe") || catLower.includes("support")) {
    catAbbr = "PS";
  } else if (catLower.includes("fitting") || catLower.includes("clamp")) {
    catAbbr = "FC";
  } else if (catLower.includes("stud") || catLower.includes("thread")) {
    catAbbr = "ST";
  }

  const cleanGrade = (gradeName || "").trim().toUpperCase().replace("GRADE", "").replace(/\s+/g, "");

  let threadCode = "FT";
  const threadLower = (threadTypeName || "").toLowerCase();
  const pitchLower = (pitch || "").toLowerCase();
  if (threadLower.includes("fine") || pitchLower.includes("fine")) {
    threadCode = "FN";
  } else if (threadLower.includes("half") || threadLower.includes("partial")) {
    threadCode = "HT";
  } else if (threadLower.includes("unf") || pitchLower.includes("unf")) {
    threadCode = "UNF";
  }

  const getFinishCode = (finishName: string): string => {
    const cleaned = (finishName || "").trim().toUpperCase();
    if (cleaned.includes("HDG") || cleaned.includes("HOT DIP") || cleaned.includes("HOT-DIP") || cleaned === "H") return "H";
    if (cleaned.includes("GI") || cleaned.includes("GALVANIZED") || cleaned === "G") return "G";
    if (cleaned.includes("SELF") || cleaned === "S") return "S";
    if (cleaned.includes("PTFE BLUE") || cleaned === "PB") return "PB";
    if (cleaned.includes("PTFE GREEN") || cleaned === "PG") return "PG";
    if (cleaned.includes("PTFE BLACK") || cleaned === "PS") return "PS";
    if (cleaned.includes("PTFE YELLOW") || cleaned === "PY") return "PY";
    if (cleaned.includes("CADMIUM") || cleaned === "C") return "C";
    if (cleaned.includes("NICKEL") || cleaned === "N") return "N";
    if (cleaned.includes("ZINC") || cleaned === "ZN" || cleaned === "Z") return "ZN";
    return cleaned ? cleaned[0] : "S";
  };
  const finCode = getFinishCode(finish);

  const sizeDigits = (size || "").trim().toUpperCase().replace(/[^0-9]/g, "");
  const lenDigits = (length || "").trim().replace(/[^0-9]/g, "");

  let basePartNo = `MF${catAbbr}${cleanGrade}${threadCode}${finCode}${sizeDigits}${lenDigits}`;

  if (existingRows && existingRows.length > 0) {
    const sameBaseRows = existingRows.filter(r => {
      if (currentRowId && r.id === currentRowId) return false;
      const existingBase = (r.partNo || "").split('-')[0].trim().toUpperCase();
      return existingBase === basePartNo.toUpperCase();
    });

    if (sameBaseRows.length > 0) {
      const currentMarking = (marking || "").trim().toUpperCase();
      const hasDifferentMarking = sameBaseRows.some(r => {
        const existingMarking = (r.marking || "").trim().toUpperCase();
        return existingMarking !== currentMarking;
      });

      if (hasDifferentMarking) {
        let maxSuffix = 0;
        sameBaseRows.forEach(r => {
          const parts = (r.partNo || "").split('-');
          if (parts.length > 1) {
            const suffixNum = parseInt(parts[1], 10);
            if (!isNaN(suffixNum) && suffixNum > maxSuffix) {
              maxSuffix = suffixNum;
            }
          }
        });
        basePartNo = `${basePartNo}-${maxSuffix + 1}`;
      }
    }
  }

  return basePartNo.toUpperCase();
}

