  const handleDuplicateRow = (targetRowId: string) => {
    if (selectedGrade && selectedGrade.rows.some(r => r.id === targetRowId)) {
      const targetIdx = selectedGrade.rows.findIndex(r => r.id === targetRowId);
      if (targetIdx === -1) return;
      const targetRow = selectedGrade.rows[targetIdx];
      const duplicated: ProductRow = {
        ...targetRow,
        id: generateId(),
      };
      const nextRows = [...selectedGrade.rows];
      nextRows.splice(targetIdx + 1, 0, duplicated);
      updateRowsInState(nextRows);
      setEditingRowId(duplicated.id);
      setSelectedRowId(duplicated.id);
      triggerToast("Row duplicated in active worksheet.");
    } else {
      let found = false;
      const duplicateInList = (list: Category[]) => {
        return list.map(c => ({
          ...c,
          subcategories: c.subcategories.map(s => ({
            ...s,
            threadTypes: s.threadTypes.map(tt => ({
              ...tt,
              grades: tt.grades.map(g => {
                const targetIdx = g.rows.findIndex(r => r.id === targetRowId);
                if (targetIdx !== -1) {
                  found = true;
                  const targetRow = g.rows[targetIdx];
                  const duplicated: ProductRow = {
                    ...targetRow,
                    id: generateId(),
                  };
                  const nextRows = [...g.rows];
                  nextRows.splice(targetIdx + 1, 0, duplicated);
                  setEditingRowId(duplicated.id);
                  setSelectedRowId(duplicated.id);
                  return { ...g, rows: nextRows };
                }
                return g;
              })
            }))
          }))
        }));
      };
      setStandardsProducts(prev => duplicateInList(prev));
      if (!found) {
        setFineThreadProducts(prev => duplicateInList(prev));
      }
      triggerToast("Row duplicated in inventory ledger.");
    }
  };

