  const [drawColor, setDrawColor] = useState('#0284c7'); // Default sky blue (Drafting/blueprint style)
  const [brushSize, setBrushSize] = useState(3);
  const [isEraser, setIsEraser] = useState(false);
  const [isDrawing, setIsDrawing] = useState(false);
  
  // Hover Magnifier/Zoom State
  const [hoveredZoom, setHoveredZoom] = useState<{
    type: 'photo' | 'drawing';
    src?: string;
    isVector?: boolean;
    vectorName?: string;
    x: number;
    y: number;
    relX?: number;
    relY?: number;
    isLocked?: boolean;
    scale?: number;
    isActiveScaleOne?: boolean;
  } | null>(null);

  const [isPanning, setIsPanning] = useState(false);
  const panStartRef = useRef({ x: 0, y: 0, relX: 50, relY: 50 });

  const handlePanStart = (e: React.MouseEvent) => {
    if (!hoveredZoom?.isLocked) return;
    setIsPanning(true);
    panStartRef.current = {
      x: e.clientX,
      y: e.clientY,
      relX: hoveredZoom.relX ?? 50,
      relY: hoveredZoom.relY ?? 50
    };
  };

  const handlePanMove = (e: React.MouseEvent) => {
    if (!isPanning || !hoveredZoom) return;
    const dx = e.clientX - panStartRef.current.x;
    const dy = e.clientY - panStartRef.current.y;
    // Sensitivity adjusts the panning speed
    const sensitivity = 0.15;
    const newRelX = Math.max(0, Math.min(100, panStartRef.current.relX - dx * sensitivity));
    const newRelY = Math.max(0, Math.min(100, panStartRef.current.relY - dy * sensitivity));
    setHoveredZoom(prev => {
      if (!prev) return null;
      return {
        ...prev,
        relX: newRelX,
        relY: newRelY
      };
    });
  };

  const handlePanEnd = () => {
    setIsPanning(false);
  };

  // Shared handlers for zoom locking and real-time cursor coordinate magnification tracking
  const handleZoomUpdate = (
    e: React.MouseEvent<HTMLDivElement>,
    type: 'photo' | 'drawing',
    src?: string,
    isVector?: boolean,
    vectorName?: string
  ) => {
    // Disable automatic hover magnification completely as requested ("IMAGE MAKE IT NOT MAGNIFYING")
    return;
  };

  const handleZoomToggleClick = (
    e: React.MouseEvent<HTMLDivElement>,
    type: 'photo' | 'drawing',
    src?: string,
    isVector?: boolean,
    vectorName?: string
  ) => {
    e.stopPropagation();

    // If there is an active zoom, check if they clicked to toggle it off or toggle to another image
    if (hoveredZoom) {
      const isSameItem = (
        hoveredZoom.type === type &&
        hoveredZoom.src === src &&
        hoveredZoom.vectorName === vectorName
      );
      if (isSameItem) {
        handleZoomClose();
        return;
      }
    }

    // Capture relative coordinates at the point of click for high-precision focal target mapping
    const rect = e.currentTarget.getBoundingClientRect();
    const relX = ((e.clientX - rect.left) / rect.width) * 100;
    const relY = ((e.clientY - rect.top) / rect.height) * 105;

    setHoveredZoom({
      type,
      src,
      isVector,
      vectorName,
      x: e.clientX,
      y: e.clientY,
      relX,
      relY,
      scale: 1.0,
      isLocked: true
    });
  };

  const handleZoomClick = (
    e: React.MouseEvent<HTMLDivElement>
  ) => {
    e.stopPropagation();
    setHoveredZoom(prev => {
      if (prev) {
        // Toggle locked status on click
        return {
          ...prev,
          isLocked: !prev.isLocked
        };
      }
      return null;
    });
  };

  const handleZoomLeave = () => {
    if (hoveredZoom?.isLocked) return;
    setHoveredZoom(null);
  };

  const renderRefCell = (rowId: string, fieldName: 'ref1Photo' | 'ref2Photo', currentValue: string | undefined) => {
    const hasValue = !!currentValue;
    const isRef1 = fieldName === 'ref1Photo';
    
    return (
      <div className="flex flex-row flex-nowrap whitespace-nowrap items-center justify-center gap-1 bg-slate-50 border border-slate-200 shadow-[0_1px_2px_rgba(0,0,0,0.03)] rounded-none p-0.5 w-[84px] mx-auto select-none">
        {/* 1. Link attachment button */}
        <button
          type="button"
          title={isRef1 ? "Attach Drawing / Blueprint URL (REF 1)" : "Attach Reference Foto / Docs URL (REF 2)"}
          onClick={(e) => {
            e.stopPropagation();
            showPrompt(
              isRef1 ? "ATTACH DRAWING URL (REF 1)" : "ATTACH REFERENCE FOTO URL (REF 2)",
              "Enter any valid browser target image web URL (Google Drive share links will automatically convert to direct embeds):",
              currentValue || "",
              "https://example.com/drawing.jpg",
              (url) => {
                let finalUrl = url;
                if (url && url.includes('drive.google.com')) {
                  const match = url.match(/\/d\/([a-zA-Z0-9-_]+)/) || url.match(/id=([a-zA-Z0-9-_]+)/);
                  if (match && match[1]) {
                    finalUrl = `https://drive.google.com/thumbnail?id=${match[1]}&sz=w800`;
                  }
                }
                handleRowFieldChange(rowId, fieldName, finalUrl);
              }
            );
          }}
          disabled={!canEdit}
          className={`w-6 h-6 rounded border flex items-center justify-center transition-all cursor-pointer ${
            canEdit
              ? isRef1
                ? 'border-amber-200 bg-amber-50/70 text-amber-600 hover:bg-amber-100 hover:border-amber-300'
                : 'border-sky-200 bg-sky-50/70 text-sky-600 hover:bg-sky-100 hover:border-sky-300'
              : 'border-slate-100 bg-[#f8fafc] text-slate-300 opacity-40 cursor-not-allowed'
          }`}
        >
          {isRef1 ? (
            <Link2 className="w-3.5 h-3.5 shrink-0" />
          ) : (
            <Paperclip className="w-3.5 h-3.5 shrink-0" />
          )}
        </button>

        {/* 2. Eye / View button */}
        <button
          type="button"
          title={hasValue ? isRef1 ? "View Drawing / Blueprint (REF 1)" : "View Physical Photo / Doc (REF 2)" : "No file attached"}
          disabled={!hasValue}
          onClick={(e) => {
            e.stopPropagation();
            if (hasValue) {
              handleZoomToggleClick(e, 'photo', currentValue);
            }
          }}
          className={`w-6 h-6 rounded border flex items-center justify-center transition-all cursor-pointer ${
            hasValue 
              ? isRef1
                ? 'border-emerald-200 bg-[#f0fdf4] text-[#16a34a] hover:bg-[#dcfce7] hover:border-[#86efac]' 
                : 'border-indigo-205 bg-[#f5f3ff] text-[#4f46e5] hover:bg-[#e0e7ff] hover:border-[#c7d2fe]'
              : 'border-slate-100 bg-[#f8fafc] text-slate-350 opacity-45 cursor-not-allowed'
          }`}
        >
          {isRef1 ? (
            <Eye className="w-3.5 h-3.5 shrink-0" />
          ) : (
            <Camera className="w-3.5 h-3.5 shrink-0" />
          )}
        </button>

        {/* 3. Delete / Trash button */}
        <button
          type="button"
          title={hasValue ? "Remove Link" : "No attachment to remove"}
          disabled={!hasValue || !canEdit}
          onClick={(e) => {
            e.stopPropagation();
            if (hasValue) {
              handleRowFieldChange(rowId, fieldName, '');
            }
          }}
          className={`w-6 h-6 rounded border flex items-center justify-center transition-all cursor-pointer ${
            hasValue && canEdit
              ? 'border-[#fee2e2] bg-[#fef2f2] text-[#dc2626] hover:bg-[#fee2e2] hover:border-[#fca5a5]' 
              : 'border-slate-100 bg-[#f8fafc] text-slate-350 opacity-45 cursor-not-allowed'
          }`}
        >
          <Trash2 className="w-3.5 h-3.5 shrink-0" />
        </button>
      </div>
    );
  };

  const handleZoomClose = (e?: React.MouseEvent) => {
    if (e) e.stopPropagation();
    if (hoveredZoom) {
      // First, transition scale back to 1 and unlock coordinates gracefully
      setHoveredZoom(prev => prev ? { ...prev, isLocked: false, scale: 1 } : null);
      // Wait for the transition to finish, then close completely
      setTimeout(() => {
        setHoveredZoom(null);
      }, 300);
    }
  };

  const handleZoomDownload = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (!hoveredZoom) return;

    if (hoveredZoom.src) {
      const a = document.createElement('a');
      a.href = hoveredZoom.src;
      a.download = `marinefasteners-inspect-${hoveredZoom.type}-${Date.now()}.png`;
      a.target = '_blank';
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
    } else if (hoveredZoom.vectorName) {
      // Export vector blueprint SVG content beautifully
      const svgEl = document.querySelector('.zoom-vector-container svg');
      if (svgEl) {
        const svgContent = new XMLSerializer().serializeToString(svgEl);
        const blob = new Blob([svgContent], { type: 'image/svg+xml;charset=utf-8' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `${hoveredZoom.vectorName.replace(/\s+/g, '-').toLowerCase()}-blueprint.svg`;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        URL.revokeObjectURL(url);
      } else {
        window.print();
      }
    }
  };
  
