  const handleTableMouseOver = (e: React.MouseEvent) => {
    const target = e.target as HTMLElement;
    const td = target.closest('td');
    if (!td) return;

    // Ignore action cell/buttons
    if (td.classList.contains('actions-cell') || td.querySelector('button') || td.querySelector('a') || td.classList.contains('actions-container')) {
      return;
    }

    const tr = td.closest('tr');
    if (!tr) return;

    const table = tr.closest('table');
    if (!table) return;

    // Find corresponding header th
    const cellIdx = td.cellIndex;
    const ths = table.querySelectorAll('thead th');
    const th = ths[cellIdx] as HTMLElement;
    if (!th) return;

    const headerText = th.textContent?.trim() || '';
    if (headerText === 'Actions' || headerText === 'Idx' || headerText === '' || headerText === 'ACTIONS') {
      setHoveredCell(null);
      return;
    }

    // Get cell value (excluding buttons or icons)
    const cellVal = td.textContent?.trim() || '';
    if (!cellVal || cellVal === '-' || cellVal === '—') {
      setHoveredCell(null);
      return;
    }

    setHoveredCell({
      rowId: tr.getAttribute('data-row-id') || '',
      field: headerText,
      value: cellVal,
      header: headerText
    });

    const rowId = tr.getAttribute('data-row-id') || '';
    if (isSimpleLayoutMode && rowId) {
      const foundRow = paginatedRows.find((r: any) => r.id === rowId);
      if (foundRow) {
        const rowData: Record<string, string> = {
          "Part No": foundRow.partNo || '-',
          "Size": foundRow.dia || '-',
          "Pitch": foundRow.pitch || '-',
          "Length": foundRow.length || '-',
          "Finish": foundRow.finish || '-',
          "Marking": foundRow.marking || '-',
          "Unit": foundRow.unit || 'PCS',
          "Opening Qty": String(foundRow.openingStock ?? 0),
          "In Stock": String(foundRow.inStock ?? 0),
          "Out Qty": String(foundRow.outGoingStock ?? 0),
          "Balance Qty": String(foundRow.balanceStock ?? 0),
          "Unit Weight": String(foundRow.unitWeight ?? 0),
          "Total Weight": String((foundRow.totalWeight ?? ((foundRow.balanceStock || 0) * (foundRow.unitWeight || 0)) ?? 0).toFixed(3)),
          "Rack Location": foundRow.rackLocation || '-'
        };
        setHoveredRow(rowData);
        return;
      }
    }

    // Extract row data for the Top View preview bar
    const rowData: Record<string, string> = {};
    const cells = tr.querySelectorAll('td');
    cells.forEach((cell, idx) => {
      const cellTh = ths[idx] as HTMLElement;
      if (cellTh) {
        const cellHeader = cellTh.textContent?.trim() || '';
        if (cellHeader && cellHeader !== 'Actions' && cellHeader !== 'Idx' && cellHeader !== 'ACTIONS') {
          rowData[cellHeader] = cell.textContent?.trim() || '';
        }
      }
    });
    setHoveredRow(rowData);
  };

