  const handleWipeSubcategoryAttachments = () => {
    if (!canEdit) return;
    if (!specKey) return;
    const isSpecialCategory = selectedCategory && 
      (selectedCategory.name.toLowerCase() === 'anchor bolts' || selectedCategory.name.toLowerCase() === 'u bolts');

    showConfirm(
      "Discard Media & Drawings",
      "Are you sure you want to delete all hand sketch drawings, uploaded photos, and engineering notes for this selected series/thread type?",
      () => {
        setAttachedSpecs(prev => {
          const updated = { ...prev };
          if (isSpecialCategory && selectedSubcategory) {
            const subcatPrefix = `${selectedSubcategory.id}_`;
            for (const key of Object.keys(updated)) {
              if (key.startsWith(subcatPrefix)) {
                delete updated[key];
              }
            }
          } else {
            delete updated[specKey];
          }
          return updated;
        });
        setIsScribbleMode(false);
      }
    );
  };

  const handleUploadDocumentFile = (type: 'dataSheet' | 'otherDoc' | 'packingDetails', e: React.ChangeEvent<HTMLInputElement>) => {
    if (currentUser?.role !== 'Admin') return;
    const file = e.target.files?.[0];
    if (!file || !specKey) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      const base64 = event.target?.result as string;
      setAttachedSpecs(prev => ({
        ...prev,
        [specKey]: {
          ...prev[specKey] || {},
          [type]: {
            name: file.name,
            dataUrl: base64
          }
        }
      }));
    };
    reader.readAsDataURL(file);
    e.target.value = '';
  };

  const handleDeleteDocumentFile = (type: 'dataSheet' | 'otherDoc' | 'packingDetails') => {
    if (currentUser?.role !== 'Admin') return;
    if (!specKey) return;
    setAttachedSpecs(prev => {
      const existing = prev[specKey] || {};
      const updated = {
        ...prev,
        [specKey]: {
          ...existing,
          [type]: undefined
        }
      };
      return updated;
    });
  };

  const handleViewDocumentFile = (type: 'dataSheet' | 'otherDoc' | 'packingDetails') => {
    if (!specKey) return;
    const doc = attachedSpecs[specKey]?.[type];
    if (!doc || !doc.dataUrl) return;

    try {
      const newTab = window.open();
      if (newTab) {
        newTab.document.write(`
          <html>
            <head>
              <title>${doc.name}</title>
              <style>body{margin:0;background:#0f172a;display:flex;align-items:center;justify-content:center;height:100vh;} iframe, img { max-width:100%; max-height:100%; border:none; }</style>
            </head>
            <body>
              ${doc.dataUrl.startsWith('data:image/') 
                ? `<div style="display:flex;align-items:center;justify-content:center;width:100%;height:100%;"><img src="${doc.dataUrl}" alt="${doc.name}" style="object-contain; max-width:95vw; max-height:95vh;" /></div>`
                : `<iframe src="${doc.dataUrl}" width="100%" height="100%"></iframe>`
              }
            </body>
          </html>
        `);
        newTab.document.close();
      } else {
        const link = document.createElement('a');
        link.href = doc.dataUrl;
        link.download = doc.name;
        link.click();
      }
    } catch (err) {
      const link = document.createElement('a');
      link.href = doc.dataUrl;
      link.download = doc.name;
      link.click();
    }
  };

  // Drawing pad canvas synchronization initializer when toggling
  useEffect(() => {
    if (isScribbleMode && canvasRef.current && specKey) {
      const canvas = canvasRef.current;
      const ctx = canvas.getContext('2d');
      if (ctx) {
        // Safe clear first
        ctx.fillStyle = '#ffffff';
        ctx.fillRect(0, 0, canvas.width, canvas.height);
        
        // Draw existing drawing back
        const existingImageString = attachedSpecs[specKey]?.drawingBase64;
        if (existingImageString) {
          const img = new Image();
          img.onload = () => {
            ctx.drawImage(img, 0, 0);
          };
          img.src = existingImageString;
        }
      }
    }
  }, [isScribbleMode, specKey]);

  // Change of Subcategory resets down the tree
  const handleSubcategorySelect = (id: string) => {
    setSelectedSubCatId(id);
    setManuallyToggledSubCatIds({ [id]: true });
    const sub = selectedCategory?.subcategories.find(s => s.id === id);
    if (sub && sub.threadTypes.length > 0) {
      const tt = sub.threadTypes[0];
      setSelectedThreadTypeId(tt.id);
      if (tt.grades.length > 0) {
        setSelectedGradeId(tt.grades[0].id);
      } else {
        setSelectedGradeId('');
      }
    } else {
      setSelectedThreadTypeId('');
      setSelectedGradeId('');
    }
  };

  // Change of ThreadType resets selected grade
  const handleThreadTypeSelect = (id: string) => {
    setSelectedThreadTypeId(id);
    const tt = selectedSubcategory?.threadTypes.find(t => t.id === id);
    if (tt && tt.grades.length > 0) {
      setSelectedGradeId(tt.grades[0].id);
    } else {
      setSelectedGradeId('');
    }
  };

  // DYNAMIC CATEGORIES, SUBCATEGORIES, THREADTYPES, AND GRADES CRUD MODIFIERS
