  const handleCancelAddRow = () => {
    setRackSavePopupRowId(null);
    setEditingRowId(null);
    triggerToast("Saved successfully!");
  };

  // Keyboard navigation for the excel save popup modal
  useEffect(() => {
    if (rackSavePopupRowId) {
      setModalFocusIndex(0); // Reset to "Add One More Row" focused by default
    }
  }, [rackSavePopupRowId]);

  useEffect(() => {
    if (!rackSavePopupRowId) return;
    const handleGlobalPopupKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'ArrowLeft' || e.key === 'ArrowRight' || e.key === 'Tab') {
        e.preventDefault();
        setModalFocusIndex(prev => (prev === 0 ? 1 : 0));
      } else if (e.key === 'Enter') {
        e.preventDefault();
        if (modalFocusIndex === 0) {
          handleConfirmAddRow();
        } else {
          handleCancelAddRow();
        }
      } else if (e.key === 'Escape') {
        e.preventDefault();
        handleCancelAddRow();
      }
    };
    window.addEventListener('keydown', handleGlobalPopupKeyDown, true);
    return () => {
      window.removeEventListener('keydown', handleGlobalPopupKeyDown, true);
    };
  }, [rackSavePopupRowId, modalFocusIndex]);

  const handleDeleteRow = (rowId: string) => {
    showConfirm(
      "Confirm Removal",
      "Are you sure you want to permanently delete this product record row from the active worksheet?",
      () => {
        if (selectedGrade && selectedGrade.rows.some(r => r.id === rowId)) {
          const filtered = selectedGrade.rows.filter(r => r.id !== rowId);
          updateRowsInState(filtered);
        } else {
          let deleted = false;
          const updateInList = (list: Category[]) => {
            return list.map(c => ({
              ...c,
              subcategories: c.subcategories.map(s => ({
                ...s,
                threadTypes: s.threadTypes.map(tt => ({
                  ...tt,
                  grades: tt.grades.map(g => {
                    if (g.rows.some(r => r.id === rowId)) {
                      deleted = true;
                      return {
                        ...g,
                        rows: g.rows.filter(r => r.id !== rowId)
                      };
                    }
                    return g;
                  })
                }))
              }))
            }));
          };
          setStandardsProducts(prev => updateInList(prev));
          if (!deleted) {
            setFineThreadProducts(prev => updateInList(prev));
          }
        }
        if (editingRowId === rowId) {
          setEditingRowId(null);
        }
        if (selectedRowId === rowId) {
          setSelectedRowId(null);
        }
        triggerToast("Row removed from inventory ledger.");
      }
    );
  };

